def modes(nums: Any) -> object {
    if (len(nums) == 0) {
        return [];
    }
    frequencies = {};
    for num in nums {
        frequencies[num] = 1 + frequencies.get(num, 0);
    }
    max_occurrences = max(frequencies.values());
    return [
        num
        for (num, frequency) in frequencies.items()
        if (frequency == max_occurrences)
    ];
}

